/// Theme extensions for a brand and brightness: `ThemeData(extensions: PxDsTheme.extensions(brand, brightness))`.
abstract final class PxDsTheme {
  static PxDsColors colors(PxDsBrand brand, Brightness brightness) => switch ((brand, brightness)) {
        (PxDsBrand.px, Brightness.light) => PxDsColors.pxLight,
        (PxDsBrand.px, Brightness.dark) => PxDsColors.pxDark,
        (PxDsBrand.treatmint, Brightness.light) => PxDsColors.treatmintLight,
        (PxDsBrand.treatmint, Brightness.dark) => PxDsColors.treatmintDark,
      };
  static PxDsElevation elevation(PxDsBrand brand, Brightness brightness) => switch ((brand, brightness)) {
        (PxDsBrand.px, Brightness.light) => PxDsElevation.pxLight,
        (PxDsBrand.px, Brightness.dark) => PxDsElevation.pxDark,
        (PxDsBrand.treatmint, Brightness.light) => PxDsElevation.treatmintLight,
        (PxDsBrand.treatmint, Brightness.dark) => PxDsElevation.treatmintDark,
      };
  static PxDsTypography typography(PxDsBrand brand) => PxDsTypography.standard;
  static PxDsPrimitives primitives(PxDsBrand brand) => switch (brand) {
        PxDsBrand.px => PxDsPrimitives.px,
        PxDsBrand.treatmint => PxDsPrimitives.treatmint,
      };
  static List<ThemeExtension<dynamic>> extensions(PxDsBrand brand, Brightness brightness) =>
      [colors(brand, brightness), elevation(brand, brightness), typography(brand)];
}
